1|// Drawing style preference for POST /api/images. Persisted in
2|// localStorage, parsed defensively. Preset ids come from the server's
3|// table so they always match; the server re-checks custom text.
4|import { IMAGE_STYLE_PRESETS } from "@/core/image-style";
5|import type { ImageStylePresetId, StyleChoice } from "@/core/image-style";
6|
7|export const IMAGE_STYLE_KEY = "lectoria.imageStyle";
8|
9|export type ImageStylePref = { kind: "preset"; id: string } | { kind: "custom"; text: string };
10|
11|export interface StylePreset {
12|  id: string;
13|  label: string;
14|}
15|
16|export const STYLE_PRESETS: StylePreset[] = IMAGE_STYLE_PRESETS.map(({ id, label }) => ({ id, label }));
17|
18|export const DEFAULT_IMAGE_STYLE: ImageStylePref = { kind: "preset", id: "denslow" };
19|
20|export const STYLE_OTHER_VALUE = "__other";
21|
22|// The select shows Other… while its custom field is open, even when the
23|// saved pref is still a preset; Escape or a preset choice closes it.
24|export function resolveStyleSelect(pref: ImageStylePref, otherOpen: boolean): string {
25|  return otherOpen || pref.kind === "custom" ? STYLE_OTHER_VALUE : pref.id;
26|}
27|
28|export const DENSLOW_CREDIT = "In the style of W. W. Denslow";
29|
30|export function parseImageStylePref(json: unknown): ImageStylePref {
31|  if (typeof json === "object" && json !== null && !Array.isArray(json)) {
32|    const pref = json as Record<string, unknown>;
33|    if (pref.kind === "preset" && typeof pref.id === "string" && STYLE_PRESETS.some((p) => p.id === pref.id)) {
34|      return { kind: "preset", id: pref.id };
35|    }
36|    if (pref.kind === "custom" && typeof pref.text === "string" && pref.text.trim().length > 0) {
37|      return { kind: "custom", text: pref.text.trim().slice(0, 60) };
38|    }
39|  }
40|  return DEFAULT_IMAGE_STYLE;
41|}
42|
43|export function loadImageStylePref(): ImageStylePref {
44|  try {
45|    if (typeof window === "undefined") return DEFAULT_IMAGE_STYLE;
46|    const raw = window.localStorage.getItem(IMAGE_STYLE_KEY);
47|    if (!raw) return DEFAULT_IMAGE_STYLE;
48|    return parseImageStylePref(JSON.parse(raw));
49|  } catch {
50|    return DEFAULT_IMAGE_STYLE;
51|  }
52|}
53|
54|export function saveImageStylePref(pref: ImageStylePref): void {
55|  try {
56|    if (typeof window === "undefined") return;
57|    window.localStorage.setItem(IMAGE_STYLE_KEY, JSON.stringify(pref));
58|  } catch {
59|    // Private mode: new pictures use the default until reload.
60|  }
61|}
62|
63|// Denslow sends nothing, so its key and prompt stay byte-identical.
64|export function requestStyleFields(pref: ImageStylePref): { style?: StyleChoice } {
65|  if (pref.kind === "custom") return { style: { custom: pref.text } };
66|  if (pref.id === "denslow") return {};
67|  return { style: { preset: pref.id as ImageStylePresetId } };
68|}
69|
70|// The credit never claims a style the request did not send.
71|export function styleCredit(fields: { style?: StyleChoice }): string {
72|  const style = fields.style;
73|  if (style === undefined) return DENSLOW_CREDIT;
74|  if ("preset" in style) {
75|    return STYLE_PRESETS.find((p) => p.id === style.preset)?.label ?? DENSLOW_CREDIT;
76|  }
77|  return style.custom;
78|}

