1|// Picture Vault: the scene picture first, then inline figures in text
2|// order, then the drawing style picker.
3|"use client";
4|
5|import { useEffect, useRef, useState } from "react";
6|import { STYLE_OTHER_VALUE, STYLE_PRESETS, resolveStyleSelect } from "../image-style";
7|import type { ImageStylePref } from "../image-style";
8|import { truncateCaption } from "./helpers";
9|import type { InlineFigure } from "./use-pictures";
10|
11|function ExpandIcon() {
12|  return (
13|    <svg width="11" height="11" viewBox="0 0 16 16" aria-hidden="true">
14|      <path d="M9.5 2.5h4v4M13.5 2.5 9 7M6.5 13.5h-4v-4M2.5 13.5 7 9" />
15|    </svg>
16|  );
17|}
18|
19|export function StylePicker({
20|  pref,
21|  onChange,
22|}: {
23|  pref: ImageStylePref;
24|  onChange: (pref: ImageStylePref) => void;
25|}) {
26|  const [custom, setCustom] = useState(pref.kind === "custom" ? pref.text : "");
27|  const [otherOpen, setOtherOpen] = useState(false);
28|  const customRef = useRef<HTMLInputElement | null>(null);
29|  const selected = resolveStyleSelect(pref, otherOpen);
30|  useEffect(() => {
31|    if (otherOpen) customRef.current?.focus();
32|  }, [otherOpen]);
33|  return (
34|    <div className="style-picker">
35|      <label className="mlabel" htmlFor="style-select">
36|        Drawing style
37|      </label>
38|      <select
39|        id="style-select"
40|        value={selected}
41|        onChange={(e) => {
42|          const next = e.target.value;
43|          if (next === STYLE_OTHER_VALUE) {
44|            setCustom(pref.kind === "custom" ? pref.text : "");
45|            setOtherOpen(true);
46|            return;
47|          }
48|          setOtherOpen(false);
49|          onChange({ kind: "preset", id: next });
50|        }}
51|        onKeyDown={(e) => {
52|          if (e.key === "Escape") setOtherOpen(false);
53|        }}
54|      >
55|        {STYLE_PRESETS.map((p) => (
56|          <option key={p.id} value={p.id}>
57|            {p.label}
58|          </option>
59|        ))}
60|        <option value={STYLE_OTHER_VALUE}>Other…</option>
61|      </select>
62|      {selected === STYLE_OTHER_VALUE ? (
63|        <div className="style-custom">
64|          <input
65|            ref={customRef}
66|            type="text"
67|            value={custom}
68|            maxLength={60}
69|            placeholder="e.g. Japanese woodblock"
70|            onChange={(e) => setCustom(e.target.value)}
71|            onKeyDown={(e) => {
72|              if (e.key === "Escape") setOtherOpen(false);
73|            }}
74|            aria-label="Custom drawing style"
75|          />
76|          <button
77|            type="button"
78|            disabled={custom.trim().length === 0}
79|            onClick={() => {
80|              const text = custom.trim();
81|              if (text.length > 0) onChange({ kind: "custom", text });
82|            }}
83|          >
84|            Use this style
85|          </button>
86|        </div>
87|      ) : null}
88|    </div>
