1|// One scene view: heading, reading column, pictures, vault, pager.
2|// Sub-page moves stay in client state; scene moves push a new route.
3|// The chapter cover and end page are sub-pages of their scene, so
4|// they never touch music state.
5|"use client";
6|
7|import { Fragment, useEffect, useMemo, useRef, useState } from "react";
8|import { useRouter } from "next/navigation";
9|import { buildNavIndex, navReducer, subPageCount, subPageKind, textPageAt } from "@/core/reader";
10|import type { NavAction, SceneView } from "@/core/reader";
11|import { loadImageStylePref, saveImageStylePref } from "../image-style";
12|import type { ImageStylePref } from "../image-style";
13|import { BandPager, Divider } from "../folio/chrome";
14|import { ImagePane } from "../folio/image-pane";
15|import { InlineFigureView, SelectionPopover } from "../folio/inline-figures";
16|import { Lightbox } from "../folio/lightbox";
