199|    }
200|  }
201|
202|  function goNext() {
203|    move({ kind: "next" });
204|  }
205|
206|  function goPrev() {
207|    move({ kind: "prev" });
208|  }
209|
210|  // Scene entry resets orientation; sub-page moves keep the heading.
211|  useEffect(() => {
212|    if (hasNavigated) headingRef.current?.focus();
213|    readColRef.current?.scrollTo(0, 0);
214|  }, [view.sceneId]);
