298|              </button>
299|            ) : (
300|              <p className="the-end">The end.</p>
301|            )}
302|          </>
303|        ) : (
304|          <>
305|            <div className="kicker">Chapter {view.ch}</div>
306|            <h1 className="chapter-title" id="scene-heading" ref={headingRef} tabIndex={-1}>
