338|                <SelectionPopover
339|                  pos={pic.popover}
340|                  popRef={pic.popRef}
341|                  onPick={() => pic.illustratePassage(pref)}
342|                />
343|              ) : null}
344|            </div>
345|          </>
346|        )}
347|      </div>
348|      <PictureVault
349|        scene={pic.card.phase === "ready" ? { url: pic.card.url, caption: pic.card.caption } : null}
350|        figures={pic.figures}
351|        onGotoScene={gotoScenePicture}
352|        onGotoFigure={gotoFigure}
353|        onOpen={pic.openLightbox}
354|        pref={pref}
355|        onPrefChange={changePref}
