5|"use client";
6|
7|import { Fragment, useEffect, useMemo, useRef, useState } from "react";
8|import { useRouter } from "next/navigation";
9|import { buildNavIndex, navReducer, subPageCount, subPageKind, textPageAt } from "@/core/reader";
10|import type { NavAction, SceneView } from "@/core/reader";
11|import { loadImageStylePref, saveImageStylePref } from "../image-style";
12|import type { ImageStylePref } from "../image-style";
13|import { BandPager, Divider } from "../folio/chrome";
14|import { ImagePane } from "../folio/image-pane";
15|import { InlineFigureView, SelectionPopover } from "../folio/inline-figures";
16|import { Lightbox } from "../folio/lightbox";
17|import { usePictures } from "../folio/use-pictures";
18|import type { InlineFigure } from "../folio/use-pictures";
19|import { PictureVault } from "../folio/vault";
20|import {
21|  chapterSetAside,
22|  coverTitleLong,
23|  markChapterEndReached,
24|  markChapterSetAside,
25|  markPanelsShownAnyway,
26|  panelsUnlocked,
27|} from "../folio/panels";
28|import type { ChapterPanel } from "../folio/panels";
29|import {
30|  BlurredThumbs,
31|  PanelsModal,
32|  PanelsOfferCard,
33|  PanelsQuietLink,
34|  SpoilerGateDialog,
35|} from "../folio/panels-modal";
36|
37|// One-shot entry intent: set just before pushing the previous scene
38|// route, so the new page opens on its last sub-page. Client memory only,
39|// never the URL, so prerendered pages stay static and a direct URL load
40|// always starts at page 0.
41|let enterAtEnd = false;
42|
43|// Set on every in-app scene push. The heading takes focus only when this
44|// is set, so first load shows no focus ring.
45|let hasNavigated = false;
46|
47|function pulse(el: HTMLElement | null) {
48|  if (!el) return;
49|  el.classList.remove("pulse");
50|  void el.offsetWidth;
51|  el.classList.add("pulse");
52|  window.setTimeout(() => el.classList.remove("pulse"), 650);
53|}
54|
55|// One scene view: sub-pages, keys, buttons, progress, chapter jump.
56|// Sub-page moves stay in client state; scene moves push a new route.
57|export function ScenePage({
58|  view,
59|  views,
60|  bookId,
61|  textVersion,
62|  bookIndex,
63|  bookTotal,
64|  panels,
65|  nextChapter,
66|}: {
67|  view: SceneView;
68|  views: { sceneId: string; pages: number }[];
69|  bookId: string;
70|  textVersion: string;
71|  bookIndex: number;
72|  bookTotal: number;
73|  panels: ChapterPanel[];
74|  nextChapter: { ch: number; firstSceneId: string } | null;
75|}) {
76|  const pic = usePictures({ bookId, textVersion, sceneId: view.sceneId });
77|  const [pref, setPref] = useState<ImageStylePref>({ kind: "preset", id: "denslow" });
78|  const router = useRouter();
79|  const index = useMemo(() => buildNavIndex(views), [views]);
80|  const cover = view.isChapterFirst;
81|  const end = view.isChapterLast;
82|  const coverLong = coverTitleLong(view.chapterTitle);
83|  const total = subPageCount(view.pages.length, cover, end);
84|  const lastPage = total - 1;
85|  const [page, setPage] = useState(() => {
86|    if (enterAtEnd) {
87|      enterAtEnd = false;
88|      return lastPage;
89|    }
90|    return 0;
91|  });
92|  const [panelsOpen, setPanelsOpen] = useState(false);
93|  const [gateOpen, setGateOpen] = useState(false);
94|  const [offerAside, setOfferAside] = useState(() => chapterSetAside(view.ch));
95|  const gateOpener = useRef<HTMLElement | null>(null);
96|  const headingRef = useRef<HTMLHeadingElement>(null);
97|  const readColRef = useRef<HTMLDivElement | null>(null);
98|  const figEls = useRef(new Map<string, HTMLElement>());
99|  const kind = subPageKind(page, view.pages.length, cover, end);
100|  const sub = kind === "text" ? (view.pages[textPageAt(page, cover)] ?? view.pages[0]) : undefined;
101|  const textIndex = textPageAt(page, cover);
102|  const atStart = view.prevSceneId === null && page === 0;
103|  const atBookEnd = view.nextSceneId === null && page === lastPage;
104|
105|  useEffect(() => {
106|    setPref(loadImageStylePref());
107|  }, []);
108|
109|  // The end page marks the chapter finished, unlocking the panels.
110|  useEffect(() => {
111|    if (kind === "end") markChapterEndReached(view.ch);
112|  }, [kind, view.ch]);
113|
114|  function changePref(next: ImageStylePref) {
115|    setPref(next);
116|    saveImageStylePref(next);
117|  }
118|
119|  function requestPanels(opener: HTMLElement | null) {
120|    if (panelsUnlocked(view.ch)) {
121|      setPanelsOpen(true);
122|      return;
123|    }
124|    gateOpener.current = opener;
125|    setGateOpen(true);
126|  }
127|
128|  function showAnyway() {
129|    markPanelsShownAnyway(view.ch);
130|    setGateOpen(false);
131|    setPanelsOpen(true);
132|  }
133|
134|  function notYet() {
135|    setGateOpen(false);
136|    gateOpener.current?.focus?.();
137|    gateOpener.current = null;
138|  }
139|
140|  function readFirst() {
141|    markChapterSetAside(view.ch);
142|    setOfferAside(true);
143|  }
144|
145|  function goNextChapter() {
146|    if (!nextChapter) return;
147|    hasNavigated = true;
148|    router.push(`/leer/${nextChapter.firstSceneId}`);
149|  }
150|
151|  const figsByN = useMemo(() => {
152|    const grouped = new Map<number, InlineFigure[]>();
153|    for (const fig of pic.figures) {
154|      const list = grouped.get(fig.endN) ?? [];
155|      list.push(fig);
156|      grouped.set(fig.endN, list);
157|    }
158|    return grouped;
159|  }, [pic.figures]);
160|
161|  function pageOf(n: number): number {
162|    const found = view.pages.findIndex((p) => p.paragraphs.some((para) => para.n === n));
163|    return found;
164|  }
165|
166|  function gotoFigure(fig: InlineFigure) {
167|    const at = pageOf(fig.endN);
168|    if (at < 0) return;
169|    setPage(at + (cover ? 1 : 0));
170|    readColRef.current?.scrollTo(0, 0);
171|    requestAnimationFrame(() => {
172|      requestAnimationFrame(() => {
173|        const el = figEls.current.get(fig.id) ?? null;
174|        el?.scrollIntoView({ block: "nearest" });
175|        pulse(el);
176|      });
177|    });
178|  }
179|
180|  function gotoScenePicture() {
181|    const img = document.querySelector(".img-pane .pane-img");
182|    pulse(img instanceof HTMLElement ? img : null);
183|  }
184|
185|  // Every pager move runs through navReducer; a new scene id means a
186|  // route push, a same-scene result means a client sub-page move.
187|  function move(action: NavAction) {
188|    pic.hidePopover();
189|    const next = navReducer({ sceneId: view.sceneId, page }, action, index);
190|    if (next.sceneId !== view.sceneId) {
191|      hasNavigated = true;
192|      if (next.page > 0) enterAtEnd = true;
193|      router.push(`/leer/${next.sceneId}`);
194|      return;
195|    }
196|    if (next.page !== page) {
197|      setPage(next.page);
198|      readColRef.current?.scrollTo(0, 0);
199|    }
200|  }
201|
202|  function goNext() {
203|    move({ kind: "next" });
204|  }
205|
206|  function goPrev() {
207|    move({ kind: "prev" });
208|  }
209|
210|  // Scene entry resets orientation; sub-page moves keep the heading.
211|  useEffect(() => {
212|    if (hasNavigated) headingRef.current?.focus();
213|    readColRef.current?.scrollTo(0, 0);
214|  }, [view.sceneId]);
215|
216|  useEffect(() => {
217|    const onKey = (event: KeyboardEvent) => {
218|      if (event.metaKey || event.ctrlKey || event.altKey) return;
219|      const target = event.target as HTMLElement | null;
220|      if (
221|        target &&
222|        (target.tagName === "INPUT" ||
223|          target.tagName === "SELECT" ||
224|          target.tagName === "TEXTAREA" ||
225|          target.isContentEditable)
226|      ) {
227|        return;
228|      }
229|      if (event.key === "ArrowRight") {
230|        event.preventDefault();
231|        goNext();
232|      } else if (event.key === "ArrowLeft") {
233|        event.preventDefault();
234|        goPrev();
235|      }
236|    };
237|    window.addEventListener("keydown", onKey);
238|    return () => window.removeEventListener("keydown", onKey);
239|  }, [page, view.sceneId, index, router]);
240|
241|  return (
242|    <>
243|      <ImagePane
244|        // The cover always shows the placeholder: nothing to picture yet,
245|        // and a cached scene picture would spoil the chapter.
246|        card={kind === "cover" ? { phase: "idle" } : pic.card}
247|        onPicture={() => pic.illustrateScene(pref)}
248|        onRetry={() => pic.illustrateScene(pref)}
249|        onClear={pic.clearScene}
250|        onOpen={pic.openLightbox}
251|        bare={kind === "cover"}
252|        onPictureChapter={
253|          kind === "cover" ? null : kind === "end" ? () => setPanelsOpen(true) : requestPanels
254|        }
255|      />
256|      <Divider />
257|      <div className="read-col" ref={readColRef} aria-label="Reading column">
258|        {kind === "cover" ? (
259|          <>
260|            <div className="kicker">Chapter</div>
261|            <p className="cover-num" data-long={coverLong} aria-label={`Chapter ${view.ch}`}>
262|              {view.ch}
263|            </p>
264|            <h1
265|              className="chapter-title cover-title"
266|              data-long={coverLong}
267|              id="scene-heading"
268|              ref={headingRef}
269|              tabIndex={-1}
270|            >
271|              {view.chapterTitle}
272|            </h1>
273|            <hr className="cover-rule" />
274|            {offerAside ? (
275|              <PanelsQuietLink onOpen={requestPanels} />
276|            ) : (
277|              <PanelsOfferCard panels={panels} onShowAnyway={showAnyway} onReadFirst={readFirst} />
278|            )}
279|            <button type="button" className="cover-begin" onClick={goNext}>
280|              Begin the chapter →
281|            </button>
282|          </>
283|        ) : kind === "end" ? (
284|          <>
285|            <div className="kicker">End of Chapter {view.ch}</div>
286|            <div className="end-card">
287|              <BlurredThumbs panels={panels} unblurredCount={Math.min(4, panels.length)} />
288|              <h2>Relive this chapter in panels</h2>
289|              <div className="panels-btns">
290|                <button type="button" className="panels-primary" onClick={() => setPanelsOpen(true)}>
291|                  Open the panels
292|                </button>
293|              </div>
294|            </div>
295|            {nextChapter ? (
296|              <button type="button" className="end-next" onClick={goNextChapter}>
297|                On to Chapter {nextChapter.ch} →
298|              </button>
299|            ) : (
300|              <p className="the-end">The end.</p>
301|            )}
302|          </>
303|        ) : (
304|          <>
305|            <div className="kicker">Chapter {view.ch}</div>
306|            <h1 className="chapter-title" id="scene-heading" ref={headingRef} tabIndex={-1}>
307|              {view.chapterTitle}
308|            </h1>
309|            <div className="scene-line">
310|              <span>
311|                Scene {view.k} of {view.n}
312|                {view.pages.length > 1 ? ` · Page ${textIndex + 1} of ${view.pages.length}` : ""}
313|              </span>
314|            </div>
315|            <div className={`body-text${textIndex === 0 ? " dropcap" : ""}`} ref={pic.viewRef}>
316|              {sub?.paragraphs.map((p, i, arr) => (
317|                <Fragment key={p.id}>
318|                  <p id={p.id} data-n={p.n} data-cont={p.cont ? true : undefined}>
319|                    {p.text}
320|                  </p>
321|                  {/* A figure for n lands after its last visible fragment. */}
322|                  {(arr[i + 1]?.n !== p.n ? (figsByN.get(p.n) ?? []) : []).map((fig) => (
323|                    <InlineFigureView
324|                      key={fig.id}
325|                      figure={fig}
326|                      onRemove={() => pic.removeFigure(fig.id)}
327|                      onRetry={() => pic.retryFigure(fig.id, pref)}
328|                      onOpen={pic.openLightbox}
329|                      refCb={(el) => {
330|                        if (el) figEls.current.set(fig.id, el);
331|                        else figEls.current.delete(fig.id);
332|                      }}
333|                    />
334|                  ))}
335|                </Fragment>
336|              ))}
337|              {pic.popover !== null ? (
338|                <SelectionPopover
339|                  pos={pic.popover}
340|                  popRef={pic.popRef}
341|                  onPick={() => pic.illustratePassage(pref)}
342|                />
343|              ) : null}
344|            </div>
345|          </>
346|        )}
