91|  const [card, setCard] = useState<SceneCard>(() => {
92|    const hit = sceneCache.get(sceneId);
93|    return hit ? { phase: "ready", url: hit.url, caption: hit.caption } : { phase: "idle" };
94|  });
95|  const [figures, setFigures] = useState<InlineFigure[]>(() =>
96|    (figureCache.get(sceneId) ?? []).filter((f) => f.phase !== "loading"),
97|  );
98|  const [popover, setPopover] = useState<{ top: number; left: number } | null>(null);
99|  const [lightbox, setLightbox] = useState<LightboxItem | null>(null);
100|  const viewRef = useRef<HTMLDivElement | null>(null);
101|  const popRef = useRef<HTMLButtonElement | null>(null);
102|  const openerRef = useRef<HTMLElement | null>(null);
103|  const busyRef = useRef(false);
104|
105|  const hidePopover = useCallback(() => setPopover(null), []);
106|
107|  const storeFigures = useCallback(
108|    (next: InlineFigure[] | ((prev: InlineFigure[]) => InlineFigure[])) => {
109|      setFigures((prev) => {
110|        const value = typeof next === "function" ? (next as (p: InlineFigure[]) => InlineFigure[])(prev) : next;
111|        figureCache.set(sceneId, value);
112|        return value;
113|      });
114|    },
115|    [sceneId],
116|  );
117|
118|  const openLightbox = useCallback((src: string, caption: string, opener: HTMLElement | null) => {
119|    openerRef.current = opener;
120|    setLightbox({ src, caption });
121|  }, []);
122|
123|  const closeLightbox = useCallback(() => {
124|    setLightbox(null);
125|    openerRef.current?.focus?.();
126|    openerRef.current = null;
127|  }, []);
128|
129|  const illustrateScene = useCallback(
130|    (pref: ImageStylePref) => {
131|      if (!sceneId || busyRef.current || sceneCache.has(sceneId)) return;
132|      busyRef.current = true;
133|      setPopover(null);
134|      setCard({ phase: "loading" });
135|      void poll({ kind: "scene", bookId, textVersion, sceneId, ...requestStyleFields(pref) })
136|        .then(({ url, caption }) => {
137|          sceneCache.set(sceneId, { url, caption });
138|          setCard({ phase: "ready", url, caption });
139|        })
140|        .catch((err: unknown) => {
141|          setCard({ phase: "error", message: err instanceof Error ? err.message : MSG_FAILED });
142|        })
143|        .finally(() => {
144|          busyRef.current = false;
145|        });
146|    },
147|    [bookId, textVersion, sceneId],
148|  );
149|
150|  const clearScene = useCallback(() => {
151|    sceneCache.delete(sceneId);
152|    setCard({ phase: "idle" });
153|  }, [sceneId]);
154|
155|  const requestFigure = useCallback(
156|    (id: string, startN: number, quote: string, pref: ImageStylePref) => {
157|      busyRef.current = true;
158|      void poll({ kind: "passage", bookId, textVersion, n: startN, ...requestStyleFields(pref) })
159|        .then(({ url }) => {
160|          storeFigures((prev) =>
161|            prev.map((f) => (f.id === id ? { ...f, phase: "ready", url, message: null } : f)),
162|          );
163|        })
164|        .catch((err: unknown) => {
165|          storeFigures((prev) =>
166|            prev.map((f) =>
167|              f.id === id
168|                ? { ...f, phase: "error", message: err instanceof Error ? err.message : MSG_FAILED }
169|                : f,
170|            ),
171|          );
172|        })
173|        .finally(() => {
174|          busyRef.current = false;
175|        });
176|    },
177|    [bookId, textVersion, storeFigures],
178|  );
179|
180|  const illustratePassage = useCallback(
181|    (pref: ImageStylePref) => {
182|      const view = viewRef.current;
183|      const sel = window.getSelection();
184|      if (!view || !sel || !sel.rangeCount || busyRef.current) return;
185|      const quote = sel.toString().trim();
186|      if (quote.length < 3) return;
187|      const entries: ParaEntry[] = [...view.querySelectorAll("p[id][data-n]")].map((el) => ({
188|        id: el.id,
189|        n: Number(el.getAttribute("data-n")),
190|      }));
191|      const startN = pickStartN(entries, paraOf(sel.anchorNode)?.id ?? null, paraOf(sel.focusNode)?.id ?? null);
192|      const endN = pickEndN(entries, paraOf(sel.anchorNode)?.id ?? null, paraOf(sel.focusNode)?.id ?? null);
193|      if (startN === null || endN === null) return;
194|      setPopover(null);
195|      sel.removeAllRanges();
196|      const id = `f${figureSeq++}`;
197|      const credit = styleCredit(requestStyleFields(pref));
198|      storeFigures((prev) => [
199|        ...prev,
200|        { id, phase: "loading", url: null, quote, startN, endN, credit, message: null },
201|      ]);
202|      requestFigure(id, startN, quote, pref);
203|    },
204|    [requestFigure, storeFigures],
205|  );
206|
207|  const retryFigure = useCallback(
208|    (id: string, pref: ImageStylePref) => {
209|      if (busyRef.current) return;
210|      const found = figureCache.get(sceneId)?.find((f) => f.id === id);
211|      if (!found || found.phase !== "error") return;
212|      storeFigures((prev) => prev.map((f) => (f.id === id ? { ...f, phase: "loading", message: null } : f)));
213|      requestFigure(id, found.startN, found.quote, pref);
214|    },
215|    [requestFigure, storeFigures, sceneId],
216|  );
217|
218|  const removeFigure = useCallback(
219|    (id: string) => {
220|      storeFigures((prev) => prev.filter((f) => f.id !== id));
221|    },
222|    [storeFigures],
223|  );
224|
225|  useEffect(() => {
226|    const view = viewRef.current;
227|    if (!view) return;
228|    let frame = 0;
229|    const onMouseUp = () => {
230|      cancelAnimationFrame(frame);
231|      frame = requestAnimationFrame(() => {
232|        const sel = window.getSelection();
233|        const text = sel?.toString().trim() ?? "";
234|        if (!sel || sel.isCollapsed || text.length < 3 || !sel.rangeCount) {
235|          setPopover(null);
236|          return;
237|        }
238|        if (!view.contains(sel.anchorNode) || !view.contains(sel.focusNode)) {
239|          setPopover(null);
240|          return;
241|        }
242|        const box = sel.getRangeAt(0).getBoundingClientRect();
243|        const host = view.getBoundingClientRect();
244|        setPopover({
245|          top: box.top - host.top - 8,
246|          left: box.left - host.left + box.width / 2,
247|        });
248|      });
249|    };
250|    view.addEventListener("mouseup", onMouseUp);
251|    return () => {
252|      cancelAnimationFrame(frame);
253|      view.removeEventListener("mouseup", onMouseUp);
254|    };
255|  }, [sceneId]);
256|
257|  useEffect(() => {
258|    if (!popover) return;
259|    const onDown = (event: MouseEvent) => {
260|      if (!popRef.current?.contains(event.target as Node | null)) setPopover(null);
261|    };
262|    const onKey = (event: KeyboardEvent) => {
263|      if (event.key === "Escape") setPopover(null);
264|    };
265|    document.addEventListener("mousedown", onDown);
266|    document.addEventListener("keydown", onKey);
267|    return () => {
268|      document.removeEventListener("mousedown", onDown);
269|      document.removeEventListener("keydown", onKey);
270|    };
271|  }, [popover]);
272|
273|  return {
274|    card,
275|    figures,
276|    popover,
277|    viewRef,
278|    popRef,
279|    illustrateScene,
280|    illustratePassage,
281|    hidePopover,
282|    clearScene,
283|    removeFigure,
284|    retryFigure,
285|    lightbox,
286|    openLightbox,
287|    closeLightbox,
288|  };
