1|// Pure image logic: validation, cache keys, prompts, quota and budget
2|// helpers. No env reads, no network, no secrets. Server modules inject
3|// the KV, store, and generator clients defined here.
4|import {
5|  ImageValidationError,
6|  parseStyleChoice,
7|  styleDescriptorLine,
8|  styleSegment,
9|} from "./image-style";
10|import type { ImageStyle } from "./image-style";
11|import { IMAGE_COST_MICRO, PROMPT_VERSION } from "./types";
12|import type { ImageKind, ImageRequest } from "./types";
13|
14|export type { ImageErrorCode, ImageKind, ImageRequest, ImageResponse } from "./types";
15|export { ImageStyleError, ImageValidationError } from "./image-style";
16|export type { ImageStyle, ImageStylePresetId, StyleChoice } from "./image-style";
17|
18|export const DAILY_IMAGE_LIMIT = 5;
19|export const QUOTA_TTL_SEC = 48 * 3600;
20|export const LOCK_TTL_SEC = 150;
21|export const MAX_PASSAGE_CHARS = 600;
22|export const MAX_SCENE_CLIP_CHARS = 1200;
23|
24|export const MSG_BAD_REQUEST = "Something went wrong there. Try again?";
25|export const MSG_QUOTA = "That's all five pictures for today. More tomorrow.";
26|export const MSG_CREDITS_OUT =
27|  "So many people loved this that we've run out of credits to share. " +
28|  "Feel free to bring your own key! Meanwhile, The Wonderful Wizard of Oz " +
29|  "is ready to read, with its soundtrack and illustrations.";
30|export const CREDITS_OUT_LIBRARY_HREF = "/";
31|export const MSG_UNAVAILABLE = "Pictures aren't available right now.";
32|export const MSG_FAILED = "That picture didn't come out. Try again?";
33|export const MSG_RETRY = "This one is taking a while. Try again in a moment.";
34|export const MSG_STYLE = "That style won't work here. Try another?";
35|
36|// Minimal store surface the route needs; Upstash REST and Blob clients
37|// implement these in server/, tests use the memory fake below.
38|export interface KV {
39|  get(key: string): Promise<string | null>;
40|  setNxEx(key: string, value: string, exSec: number): Promise<boolean>;
41|  set(key: string, value: string): Promise<void>;
42|  incr(key: string): Promise<number>;
43|  incrBy(key: string, by: number): Promise<number>;
44|  decr(key: string): Promise<number>;
45|  decrBy(key: string, by: number): Promise<number>;
46|  expire(key: string, sec: number): Promise<void>;
47|  releaseIfToken(key: string, token: string): Promise<boolean>;
48|}
49|
50|export interface ImageStore {
51|  findUrl(path: string): Promise<string | null>;
52|  save(path: string, bytes: Uint8Array): Promise<string>;
53|}
54|
55|export interface ImageGenerator {
56|  generate(prompt: string): Promise<Uint8Array>;
57|}
58|
59|function isRecord(json: unknown): json is Record<string, unknown> {
60|  return typeof json === "object" && json !== null && !Array.isArray(json);
61|}
62|
63|// Strict parse at the trust boundary: exact fields only, so a client
64|// bug cannot silently spend budget on a misread request.
65|export function parseImageRequest(json: unknown): ImageRequest {
66|  if (!isRecord(json)) throw new ImageValidationError();
67|  const { kind } = json;
68|  if (kind === "passage") {
69|    const keys = Object.keys(json).sort().join(",");
70|    if (keys !== "bookId,kind,n,textVersion" && keys !== "bookId,kind,n,style,textVersion") {
71|      throw new ImageValidationError();
72|    }
73|    if (typeof json.bookId !== "string" || json.bookId.length === 0) throw new ImageValidationError();
74|    if (typeof json.textVersion !== "string" || json.textVersion.length === 0) {
75|      throw new ImageValidationError();
76|    }
77|    if (typeof json.n !== "number" || !Number.isInteger(json.n)) throw new ImageValidationError();
78|    const style = parseStyleChoice(json.style);
79|    return {
80|      kind: "passage",
81|      bookId: json.bookId,
82|      textVersion: json.textVersion,
83|      n: json.n,
84|      ...(style === undefined ? {} : { style }),
85|    };
86|  }
87|  if (kind === "scene") {
88|    const keys = Object.keys(json).sort().join(",");
89|    if (keys !== "bookId,kind,sceneId,textVersion" && keys !== "bookId,kind,sceneId,style,textVersion") {
90|      throw new ImageValidationError();
91|    }
92|    if (typeof json.bookId !== "string" || json.bookId.length === 0) throw new ImageValidationError();
93|    if (typeof json.textVersion !== "string" || json.textVersion.length === 0) {
94|      throw new ImageValidationError();
95|    }
96|    if (typeof json.sceneId !== "string" || json.sceneId.length === 0) throw new ImageValidationError();
97|    const style = parseStyleChoice(json.style);
98|    return {
99|      kind: "scene",
100|      bookId: json.bookId,
101|      textVersion: json.textVersion,
102|      sceneId: json.sceneId,
103|      ...(style === undefined ? {} : { style }),
104|    };
105|  }
106|  throw new ImageValidationError();
107|}
108|
109|export interface BookRef {
110|  id: string;
111|  textVersion: string;
112|  paragraphNs: Set<number>;
113|  sceneIds: Set<string>;
114|}
115|
116|// Checks the parsed request against the frozen book text.
117|export function validateAgainstBook(req: ImageRequest, book: BookRef): void {
118|  if (req.bookId !== book.id) throw new ImageValidationError();
119|  if (req.textVersion !== book.textVersion) throw new ImageValidationError();
120|  if (req.kind === "passage") {
121|    if (!book.paragraphNs.has(req.n)) throw new ImageValidationError();
122|    return;
123|  }
124|  if (!book.sceneIds.has(req.sceneId)) throw new ImageValidationError();
125|}
126|
127|// One paragraph maps to one image; one scene maps to one image. A styled
128|// image keeps the same base with a style segment before the file name, so
129|// an omitted style keys byte-identically to today.
130|export function imageKey(req: ImageRequest): string {
131|  const base = `images/${req.bookId}/${req.textVersion}/${PROMPT_VERSION}`;
132|  const file = req.kind === "passage" ? `p${req.n}.webp` : `scene-${req.sceneId}.webp`;
133|  return req.style === undefined ? `${base}/${file}` : `${base}/${styleSegment(req.style)}/${file}`;
134|}
135|
136|export function indexKeyFor(key: string): string {
137|  return `img:index:${key}`;
138|}
139|
140|export function lockKeyFor(key: string): string {
141|  return `img:lock:${key}`;
142|}
143|
144|export function quotaKeys(args: { day: string; ipHash: string; anonId: string }): {
145|  ip: string;
146|  anon: string;
147|} {
148|  return {
149|    ip: `img:quota:ip:${args.day}:${args.ipHash}`,
150|    anon: `img:quota:anon:${args.day}:${args.anonId}`,
151|  };
152|}
153|
154|export function spendKey(): string {
155|  return "img:spend:micro";
156|}
157|
158|// Daily spend counter for our key. The day is the UTC day string
159|// YYYY-MM-DD the caller already uses for quota keys, so the daily
160|// cap resets on UTC rollover together with per-person quota.
161|export const DAILY_SPEND_TTL_SEC = 48 * 3600;
162|
163|export function dailySpendKey(day: string): string {
164|  return `img:spend:daily:${day}`;
165|}
166|
167|export function overQuota(count: number): boolean {
168|  return count > DAILY_IMAGE_LIMIT;
169|}
170|
171|export function budgetExceeded(totalAfterReserve: number, capMicro: number): boolean {
172|  return totalAfterReserve > capMicro;
173|}
174|
175|export function imageCostMicro(): number {
176|  return IMAGE_COST_MICRO;
177|}
178|
179|// Lets the route compare lock tokens without touching Redis twice.
180|export function canRelease(expected: string, actual: string | null): boolean {
181|  return actual !== null && actual === expected;
182|}
183|
184|function clip(text: string, max: number): string {
185|  const clean = text.replace(/\s+/g, " ").trim();
186|  if (clean.length <= max) return clean;
187|  return clean.slice(0, max).trimEnd();
188|}
189|
190|// Prompt from trusted server-side book text only. The client sends
191|// ordinals and ids, never free text, so there is no injection path. Only
192|// the optional parsed style reaches the prompt, never raw client text.
193|export function buildPrompt(args: {
194|  kind: ImageKind;
195|  passageText: string;
196|  sceneTitle: string;
197|  sceneClip: string;
198|  style?: ImageStyle;
199|}): string {
200|  const denslow =
201|    "Illustration in the style of W. W. Denslow's 1900 first-edition " +
202|    "illustrations for The Wonderful Wizard of Oz: flat color, bold black " +
